const lessonOrder=[14,12,0,1,2,3,4,5,6,13,7,8,10,11,9];
const lessonMinutes=[2,5,2,3,4,4,7,5,6,4,4,5,4,5,0];
const teacherGuides=[{"say":"Две команды пришли в одну переговорку. Обе считают, что забронировали её. Спроектируем приложение, в котором так не получится.","steps":["Покажи времена двух броней.","Спроси: «Что надо запретить, чтобы люди не столкнулись в комнате?»","Выберите правила: пересечения запрещены, соседние встречи разрешены."],"qa":[{"q":"Что приложение разрешает?","a":"Создать бронь, посмотреть расписание, перенести и отменить свою бронь."},{"q":"Что оно запрещает?","a":"Пересечение активных броней одной комнаты, интервал с концом раньше начала и отмену чужой брони."},{"q":"Можно ли начать следующую встречу ровно в 11:00, если предыдущая закончилась в 11:00?","a":"Да. Это выбранное правило нашего приложения."}],"extra":"Не добавляй пока оплату, роли администратора и повторяющиеся встречи. Запиши их как возможное развитие.","sources":[],"explain":["В нашем учебном офисе есть комната «Север». Команда А заняла её с 10:00 до 11:00. Команда Б пытается занять с 10:30 до 11:30. Полчаса совпадают: такое бронирование надо отклонить.","Сначала выбираем правила приложения вместе с группой. Мы сами принимаем правило: соседние встречи разрешены, отменять может организатор. Это решения для нашего примера, а не универсальные требования DDD."],"lecture":"Используем формат совместного проектирования из заметок преподавателю. Выбор правил — наша активность."},{"say":"Договоримся о словах. Комната — место. Бронь — кто и когда занимает это место.","steps":["Укажи комнату, бронь и интервал на слайде.","Спроси, что остаётся после отмены встречи."],"qa":[{"q":"Что хранит каждый объект?","a":"Room: номер, название, вместимость. Booking: номер брони, комната, организатор, интервал, статус. TimeInterval: начало и конец."},{"q":"Встречу отменили. Что произойдёт с бронью?","a":"Организатор отменяет её. Бронь остаётся в истории, но больше не занимает комнату."},{"q":"Нужен ли отдельный Meeting?","a":"Пока нет. Мы не ведём повестку и участников. Класс понадобится при появлении таких правил."}],"extra":"Полный User с профилем сейчас не нужен. В бронь передаём идентификатор организатора.","sources":[],"explain":["Комната существует и без встреч. В ней есть название и вместимость. Бронь — отдельная запись: кто занял эту комнату и на какое время. Поэтому Room и Booking выполняют разную работу.","Интервал — пара начала и конца. В нём удобно проверять корректность времени и пересечение. Организатор — человек, создавший бронь; пока достаточно его идентификатора, полный профиль не нужен."],"lecture":"Лекция «Общий словарь терминов»: одно значение термина в разговоре и коде."},{"say":"Подвинем второй интервал. Посмотрим, когда две встречи можно разрешить.","steps":["Подвинь ползунок на 10:30 — получится пересечение.","Передвинь на 11:00 — время свободно.","Объясни правило на двух числовых примерах."],"qa":[{"q":"10:00–11:00 и 11:00–12:00 пересекаются?","a":"Нет. Конец первого интервала не входит в занятое время."},{"q":"Как проверить пересечение?","a":"A.Start < B.End и B.Start < A.End. Оба условия должны выполняться."},{"q":"Где проверить начало и конец?","a":"При создании TimeInterval: Start должен быть меньше End."}],"extra":"На экране один день и одна временная зона. В настоящем приложении сравнивают полные моменты времени, а не только часы. Даты и часовые пояса тоже учитываются.","sources":[],"explain":["Первая встреча занимает 10:00–11:00. Если вторая начинается в 10:30, они пересекаются. Если в 11:00, первая уже закончилась: вторую разрешаем.","Проверка A.Start < B.End и B.Start < A.End ловит и частичное пересечение, и случай, когда одна встреча полностью внутри другой. Строгий знак < разрешает соседние интервалы. У каждого интервала начало обязательно раньше конца."],"lecture":"Расширяем моделирование конкретным примером. Формула пересечения — правило нашего интервала."},{"say":"Переносим бронь №42. Время изменилось, номер остался: это та же бронь.","steps":["Покажи номер 42 до и после переноса.","Спроси, появилась ли новая бронь.","Объясни сущность и объект значения через этот пример."],"qa":[{"q":"Брони двух разных команд на одно время равны?","a":"Нет. У них разные номера. Их интервалы могут быть равны, сами брони — нет."},{"q":"Почему Booking — Entity?","a":"По идентификатору узнаём ту же бронь после изменения времени или статуса."},{"q":"Почему TimeInterval — Value Object?","a":"Нам важны начало и конец. Два интервала с одинаковыми полными границами взаимозаменяемы."},{"q":"Объект значения обязательно struct?","a":"Нет. Это смысл объекта. Он может быть классом или структурой."}],"extra":"record помогает получить равенство по значениям, но сам не проверяет правила и не гарантирует глубокую неизменяемость. Его свойства или вложенная коллекция могут изменяться.","sources":[["Records в C#","https://learn.microsoft.com/en-us/dotnet/csharp/language-reference/builtin-types/record"],["Эрик Эванс: DDD Reference","https://www.domainlanguage.com/ddd/reference/"]],"explain":["Переносим бронь №42 с 10:00 на 12:00. Человек по-прежнему видит свою бронь №42, а не новую. Мы узнаём её по идентификатору. Такой объект называется сущностью — Entity.","Интервал 10:00–11:00 и другой интервал 10:00–11:00 означают одинаковое время. Отдельный номер им не нужен: сравниваем начало и конец. Это объект значения — Value Object. При переносе заменяем интервал брони новым."],"lecture":"Лекция «Моделирование предметной области»: сущности и объекты значения."},{"say":"У одной брони нет информации обо всех остальных встречах. Для проверки занятости ей нужно расписание комнаты. Давайте распределим проверки между этими объектами.","steps":["Сначала спроси: «Где проверим, занята ли комната?»","Кнопкой «Следующий объект» раскрой четыре объекта.","У каждого назови данные и одну проверку."],"qa":[{"q":"Кто видит другие брони и проверяет пересечения?","a":"RoomSchedule. Отдельная Booking знает свой интервал, но не все остальные брони."},{"q":"Что делает Room?","a":"Хранит сведения о комнате. В нашем варианте правила занятости находятся в расписании."},{"q":"Что означает рамка?","a":"Изменения этих объектов согласовываем. Бронь создают и меняют через расписание."},{"q":"Что такое агрегат и его корень?","a":"Агрегат — группа объектов, чьи правила поддерживают вместе. Корень — объект, через который меняют группу. Здесь это RoomSchedule."},{"q":"Можно ли иначе?","a":"Да. Но нужно объяснить, кто видит другие брони и как сохранение защищает правило."}],"extra":"В учебном примере одно расписание относится к комнате и дню. Встречи через полночь пока не разрешаем. Агрегат не равен таблице. Хранилище должно защищать запись общей версии; проверки в памяти недостаточно.","sources":[["Модель и агрегаты в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/microservice-domain-model"],["Эрик Эванс: DDD Reference","https://www.domainlanguage.com/ddd/reference/"]],"explain":["Одна Booking знает только свою встречу. Она может проверить, кто её отменяет. Но для проверки занятости нужны другие встречи этой комнаты. Поэтому вводим RoomSchedule — расписание комнаты на один день.","В расписании есть список броней. Book сначала смотрит активные брони и ищет пересечение. Если не нашёл — добавляет новую Booking. TimeInterval проверяет сами границы времени; Booking хранит автора и статус. Room хранит название и вместимость.","Изменяем брони через предусмотренные действия, а не выдаём всем изменяемый список. В DDD группу объектов, которые меняют под контролем одного входа, называют агрегатом. Здесь этим входом служит RoomSchedule. Название полезно знать, но на паре достаточно понять проверку занятости."],"lecture":"Лекция «Моделирование предметной области»: объекты с поведением. Агрегат — дополнительное пояснение по справочнику Эрика Эванса."},{"say":"Появился бот. Он должен разрешать и запрещать те же брони, что и сайт.","steps":["Спроси: «Бот тоже должен запрещать двойную бронь. Где он возьмёт проверку?»","Покажи общий вход к расписанию."],"qa":[{"q":"Кто проверяет формат даты?","a":"Экран или входной API разбирает ввод. Сервер тоже проверяет его: доверять одной проверке в браузере нельзя."},{"q":"Кто проверяет свободное время?","a":"RoomSchedule. Это правило действует для любого интерфейса."},{"q":"Что будет при разных проверках?","a":"Бот разрешит бронь, которую сайт запрещает. Исправления придётся повторять."},{"q":"Почему не вынести всё в один сервис?","a":"Для сложных правил удобнее держать поведение у объектов с нужными данными. Для простого справочника более простое решение нормально."}],"extra":"Методы не нужны каждому классу ради DDD. Доменный сервис применяют, если правило нельзя естественно отнести к одному объекту. Application организует загрузку и сохранение; это другая ответственность.","sources":[["Когда нужна богатая модель","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/microservice-domain-model"],["Мартин Фаулер: модель с поведением","https://martinfowler.com/bliki/AnemicDomainModel.html"]],"explain":["Представь, что проверка пересечений написана в обработчике кнопки на сайте. Завтра добавили Telegram-бота. Если бот просто пишет запись в базу, он обходит эту проверку и создаёт двойную бронь.","Сайт и бот должны вызвать одно действие создания брони. Оно передаёт запрос расписанию; расписание применяет правила. Тогда новое правило исправляем в модели один раз, и оба входа получают одинаковое поведение.","Проверить формат даты на экране полезно: человеку сразу показывают ошибку. Это не заменяет проверку правил в модели, потому что запрос может прийти через API, бота или другой экран."],"lecture":"Лекция «Реализация»: размещение действий в модели. На паре обсуждаем новый вход — бота."},{"say":"Экран получает ввод. Действие приложения загружает расписание. Расписание проверяет бронь. Затем результат сохраняют.","steps":["Пройди четыре шага слева направо.","На каждом шаге объясни конкретное действие."],"qa":[{"q":"Добавили бота. Переписываем проверку занятости?","a":"Нет. Он вызывает то же действие и ту же модель."},{"q":"Что находится в UI?","a":"Экран или обработчик сообщения: ввод и результат."},{"q":"Что находится в Application?","a":"Действие «Забронировать»: загрузить расписание, вызвать Book, сохранить."},{"q":"Что находится в Domain?","a":"RoomSchedule, Booking, TimeInterval и их правила."},{"q":"Что находится в Infrastructure?","a":"Конкретная работа с базой и отправка сообщений."},{"q":"Это схема зависимостей?","a":"Нет. Здесь показан порядок выполнения запроса. Зависимости кода показаны отдельно."}],"extra":"actorId берётся из проверенной учётной записи, не из произвольного поля формы. Для начала хватит папок. Сценарий использует контракт сохранения; реализацию подключают при запуске.","sources":[["Слои DDD в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"]],"explain":["Человек выбрал комнату и время. UI принимает эти значения. Application — код сценария «создать бронь»: получает расписание, вызывает Book, затем просит сохранить результат.","Domain — сами RoomSchedule, Booking и TimeInterval. Они знают правила бронирования. Infrastructure — код конкретного хранилища: например, работа с EF Core и PostgreSQL. На слайде стрелки показывают последовательность действий, а не зависимости проектов.","Для учебного приложения хватит папок. Раздельные сборки пригодятся, когда нужно запретить лишние ссылки между частями кода. DDD не требует отдельных серверов для каждого слоя."],"lecture":"Лекция «Слоистая архитектура»: UI, Application, Domain, Infrastructure."},{"say":"Статус не записывают напрямую. Вызывают Cancel, который проверяет организатора.","steps":["Спроси: «Кто может отменить эту бронь?»","Сравни запрос автора и другого человека."],"qa":[{"q":"Что плохого в «статус = отменена» снаружи?","a":"Так можно обойти проверку организатора. Поэтому сеттер закрывают."},{"q":"Кто отменяет?","a":"Только организатор в нашей модели. Приложение передаёт идентификатор вошедшего пользователя."},{"q":"Что делать при повторной отмене?","a":"Мы выбрали повтор без изменения результата. Своя уже отменённая бронь не меняется."},{"q":"Где Cancel?","a":"Booking проверяет свои данные. В нашем варианте действие вызывают через RoomSchedule, чтобы сохранить изменение расписания."}],"extra":"Если администратору тоже разрешат отмену, это новое требование. Не вводим роли заранее. Отмена сохраняет историю, но убирает бронь из занятости.","sources":[],"explain":["Бронь активна и занимает время. Организатор нажал «отменить». Вызываем Booking.Cancel и проверяем, что запрос пришёл от автора этой брони. После отмены она освобождает время, но остаётся в истории.","Если снаружи доступно booking.Status = Canceled, другой код может обойти проверку автора. Поэтому статус меняется внутри Cancel. Для нашего приложения повторная отмена ничего не меняет. Это выбранное поведение, его стоит закрепить тестом."],"lecture":"Практика TaxiOrder: объект ограничивает допустимые изменения состояния."},{"say":"Оба запроса прочитали свободное время до первой записи. Поэтому обе проверки прошли.","steps":["Без проверки версии нажми «Следующий шаг» три раза.","Нажми «С проверкой версии» и пройди четыре шага.","Объясни, почему проверка времени и защита записи решают разные проблемы."],"qa":[{"q":"Почему «время свободно» недостаточно?","a":"Между проверкой и записью другой запрос может занять время."},{"q":"Зачем второй запрос читает снова?","a":"После отказа его данные устарели. Новая версия уже содержит первую бронь."},{"q":"Где версия?","a":"У общего расписания комнаты. Оба запроса должны изменять одну и ту же версию."},{"q":"Почему версия каждой новой брони не поможет?","a":"Это две разные записи. Они не обновляют одну строку и не конфликтуют между собой."},{"q":"Что значит атомарно?","a":"Проверка версии и запись — одна неделимая операция. Между ними нельзя вклиниться."}],"extra":"В БД обновляют строку RoomSchedule с условием Version = expectedVersion и записывают брони в той же транзакции. При нуле обновлённых строк откатывают. Добавление дочерней Booking само не обязано менять версию корня. EF Core проверяет token при UPDATE/DELETE; два разных INSERT так не защищены. Просто объявить token у Booking недостаточно.","sources":[["Конфликты версии в EF Core","https://learn.microsoft.com/en-us/ef/core/saving/concurrency"]],"explain":["Два человека почти одновременно нажали «забронировать». Оба прочитали расписание, пока в нём ещё пусто. Поэтому оба честно получили ответ «свободно». Проверка в памяти сработала, но данные уже могли измениться перед записью.","У расписания есть номер версии. Оба прочитали версию 7. Первый сохраняет бронь и меняет версию на 8. Второй пытается сохранить изменения версии 7 — хранилище отклоняет запись. После повторного чтения второй запрос уже видит чужую бронь.","Проверка старой версии и запись должны выполняться в базе вместе. Для этой схемы обновляем общую строку расписания и добавляем бронь одной транзакцией. Версия только у каждой новой брони не помогает: два разных INSERT не конкурируют за одну строку."],"lecture":"Дополнение к курсу о работе двух запросов. Сверено с EF Core: concurrency token при UPDATE/DELETE; общий INSERT не защищён автоматически."},{"say":"Бронь сохранилась. Сообщение не отправилось. В нашей модели комнату всё равно считаем занятой.","steps":["Если осталось время, покажи ошибку доставки сообщения.","Спроси: «Комната теперь свободна или по-прежнему занята?»"],"qa":[{"q":"Ошибка сообщения отменяет бронь?","a":"В нашем приложении нет. В другом продукте может быть иное правило."},{"q":"Как не потерять задачу доставки?","a":"Записать бронь и задачу отправки в одной транзакции. Отдельный отправитель повторяет попытки."},{"q":"Сообщение придёт ровно один раз?","a":"Не обязательно. Повторы могут дать дубли. При необходимости нужна защита от повторной обработки."}],"extra":"Outbox — дополнительный приём работы с БД и сообщениями. Не обязательная часть DDD и не задание этой пары.","sources":[],"explain":["Бронь уже сохранена, а Telegram временно недоступен. В нашем приложении это не освобождает комнату: встреча забронирована независимо от сообщения.","Можно записать в ту же базу задачу на отправку вместе с бронью. Отдельный отправитель заберёт её и повторит попытку при ошибке. Это outbox. Тема дополнительная: она показывает техническую задачу вокруг модели, но не нужна для основных решений этой пары."],"lecture":"Дополнительная тема, не повторение лекции и не обязательная реализация."},{"say":"Переносим встречу. Номер брони сохраняем. Новый интервал проверяем заново.","steps":["Спроси: «Пользователь переносит встречу. Что проверим?»","Нажми «На 12:00».","Назови четыре проверки с экрана."],"qa":[{"q":"Какие правила уже есть?","a":"Организатор, активный статус, корректный интервал, отсутствие пересечений."},{"q":"Какую операцию добавим?","a":"RoomSchedule.Reschedule(id, newInterval, actor). Проверяет другие брони и меняет интервал этой."},{"q":"Почему исключаем саму бронь?","a":"Иначе она будет мешать своему переносу. Проверяем другие активные брони."},{"q":"Что при занятом времени?","a":"Отказать и оставить старый интервал. Сначала проверять, затем менять."},{"q":"Версия при переносе нужна?","a":"Да. До записи другой запрос может изменить расписание."}],"extra":"Перенос в другую комнату затрагивает два расписания. Это отдельное требование, сейчас его не добавляем.","sources":[],"explain":["Новый запрос от пользователя: перенести свою встречу. Номер брони сохраняем. Проверяем автора, активный статус и новое время. Расписание сравнивает новый интервал с другими активными бронями.","Текущую бронь исключаем из сравнения: она не должна мешать переносу самой себя. Если новое время занято — отказываем и оставляем старое. Если свободно — меняем интервал и сохраняем с проверкой версии расписания.","На паре переносим только внутри одного дня и одной комнаты. Перенос в другую комнату или через полночь потребует новых решений. Не обещаем, что нынешняя схема автоматически покрывает их."],"lecture":"Применение модели к новому требованию."},{"say":"Вот где у нас оказались проверки. Давайте возьмём одно действие — перенос встречи — и посмотрим, какие из этих объектов ему нужны.","steps":["Спроси: «Какой объект проверяет, что время свободно?»","Спроси: «Что используем повторно, если добавим бота?»","Свяжи два приёма с ValueType и TaxiOrder."],"qa":[{"q":"Что узнаёте в ValueType?","a":"Равенство по содержимому. В задании сравнивают публичные свойства, поля не участвуют."},{"q":"Что узнаёте в TaxiOrder?","a":"Сам заказ проверяет допустимые действия. Снаружи не выставляют статус напрямую."},{"q":"Что делает репозиторий водителей?","a":"Выдаёт водителя по идентификатору. Заказ он не меняет."},{"q":"Что останется при замене сайта ботом?","a":"Правила и действие приложения. Поменяется ввод и вывод."},{"q":"DDD полностью нужен всегда?","a":"Нет. Он полезен для сложных меняющихся правил. Простому справочнику сложная модель может не понадобиться."}],"extra":"Основной маршрут — план на 60 минут с обсуждениями, не гарантия скорости группы. Если задержались, сокращай рассказ, а не совместный выбор классов. Бонус после итогов в час не входит.","sources":[],"explain":["На слайде видны три места проверок. TimeInterval отвечает за корректное время. Booking — за автора и состояние одной брони. RoomSchedule — за пересечения разных броней.","Можно спросить группу обычным языком: «Мы добавили бота. Какой код он сможет использовать?» Ответ: тот же сценарий создания брони и те же классы модели. Переписывать проверку времени в боте не надо.","Связь с домашними заданиями: в ValueType сравнивают значения по содержимому. В TaxiOrder сам заказ ограничивает переходы состояния. В обоих случаях класс должен выражать смысл и правила, а не только хранить поля."],"lecture":"Связь активности с ValueType и TaxiOrder."},{"say":"Uber группировал сервисы по задачам бизнеса. Shopify разделял одно приложение на модули. Границы нужны в обоих случаях.","steps":["Покажи области Uber и модули Shopify.","Расскажи про точку входа области и замену расчёта налогов.","Объясни повседневный пример с требованием переноса встречи."],"qa":[{"q":"Зачем Uber объединял сервисы?","a":"Чтобы другие команды обращались к понятной точке входа области вместо всех внутренних сервисов."},{"q":"Что здесь связано с DDD?","a":"Области бизнеса и правила их взаимодействия. Uber прямо пишет, что DOMA использует идеи DDD вместе с другими подходами."},{"q":"Нужен сервис каждому классу?","a":"Нет. Shopify показывает пользу границ внутри одного приложения."},{"q":"Это схема компаний сейчас?","a":"Нет. Это исторические разборы: Uber 2020, Shopify 2019 и ретроспектива 2024. Схемы на слайде — наши иллюстрации."},{"q":"Как это выглядит в обычной работе разработчика?","a":"Приходит требование: организатор может перенести встречу. Уточняем, кто организатор, можно ли переносить отменённую бронь и что делать при пересечении. Добавляем действие Reschedule в модель, проверяем правила тестами. Сайт и бот вызывают это действие, а не пишут каждый свою проверку."},{"q":"Какой практический результат?","a":"При изменении правила исправляем его в одном месте. Новые экраны используют ту же проверку. Команды меньше зависят от внутреннего устройства чужих модулей."}],"extra":"Uber описывает области карт, тарифа и подбора водителя. DOMA не синоним DDD. Shopify пишет о модулях заказов, доставки, товаров и счетов и о замене расчёта налогов после изоляции зависимостей. В 2024 компания подчёркивает: названия бизнес-областей не всегда совпадают с реальными зависимостями кода. Не обещаем, что это вся архитектура компаний в 2026 году.","sources":[["Uber Engineering, 2020","https://www.uber.com/us/en/blog/microservice-architecture/"],["Shopify Engineering, 2019","https://shopify.engineering/deconstructing-monolith-designing-software-maximizes-developer-productivity"],["Shopify: выводы 2024","https://shopify.engineering/a-packwerk-retrospective"]],"explain":["В Uber было много взаимосвязанных сервисов. В статье 2020 года компания описала их объединение в области: карты, тарифы, подбор водителя. Для обращения к области дают точку входа, чтобы клиентам не требовалось знать все внутренние сервисы. Это DOMA: подход использует DDD вместе с другими идеями.","Shopify выбрал другой путь: разделение одного приложения на модули, например заказы и доставку. В статье 2019 года есть практический результат: после выделения расчёта налогов его реализацию стало проще заменить. DDD не обязывает разносить всё по микросервисам.","Для нашей разработки это выглядит приземлённо. Приходит задача «перенос встречи». Разработчик уточняет правила с тем, кто пользуется системой, добавляет Reschedule в модель, проверяет сценарии тестами. Сайт и бот вызывают одно действие. В статье Shopify 2024 года есть и оговорка: красивые названия модулей сами по себе не устраняют реальные зависимости кода."],"lecture":"Исторические инженерные статьи Uber и Shopify; это не точные текущие схемы компаний."},{"say":"Здесь стрелки показывают, какие части кода знают друг о друге. Это другая схема, не порядок запроса.","steps":["Объясни стрелку: «использует код».","Покажи, что Domain не зависит от конкретной базы.","Спроси, какие классы менять при замене хранилища."],"qa":[{"q":"Как сменить базу, не переписывая Booking и TimeInterval?","a":"Реализовать тот же контракт сохранения для другой базы. Правила останутся в Domain."},{"q":"Почему Infrastructure зависит от Domain?","a":"Сохранение знает типы и контракты модели. Booking при этом не зависит от EF Core."},{"q":"Как Application сохраняет?","a":"Вызывает контракт. Реализацию связывают при запуске."},{"q":"Где контракт репозитория?","a":"Здесь в Domain. Можно выбрать Application. Главное — не привязывать правила к конкретной базе."},{"q":"Почему в лекции стрелки могли быть другими?","a":"Там Infrastructure включает общие вспомогательные типы. Здесь это конкретные БД и интеграции. Состав слоя отличается."},{"q":"Нужны четыре проекта?","a":"Нет. Можно начать с папок. Проекты помогают жёстче контролировать ссылки."}],"extra":"Это один современный вариант организации с независимой моделью. Запуск приложения связывает реализации и не показан на схеме. DI подробно будет в следующих блоках.","sources":[["Зависимости слоёв в .NET","https://learn.microsoft.com/en-us/dotnet/architecture/microservices/microservice-ddd-cqrs-patterns/ddd-oriented-microservice"]],"explain":["Здесь стрелка означает «этот код использует тот код». UI вызывает сценарий Application. Сценарий работает с Domain. Domain знает, когда встреча допустима, но не знает названий кнопок и не отправляет SQL-запросы.","Для сохранения нужен интерфейс хранилища: например, операции Load — загрузить расписание и Save — сохранить изменения. Класс, работающий с конкретной базой, реализует этот интерфейс. При запуске связываем сценарий с реализацией. Если поменяем базу, проверку пересечений не переписываем.","Это один вариант слоистой архитектуры с независимой моделью. Размещение интерфейса хранилища в Domain или Application зависит от проекта. Главное здесь — не путать движение запроса с зависимостями кода. На паре не нужно изучать DI-контейнер."],"lecture":"Развитие идеи слоёв. Разные направления выполнения и зависимостей показаны разными схемами."},{"say":"DDD — проектирование вокруг правил предметной области. Сначала выясняем, как работает бронирование, затем выражаем эти правила в модели и коде.","steps":["Коротко прочитай определение DDD.","Назови пример правила про одну комнату.","Перейди к Uber и Shopify."],"qa":[{"q":"Что значит предметная область?","a":"Та часть реальной работы, которую автоматизируем: например, бронирование комнат."},{"q":"Что DDD меняет в разработке?","a":"Обсуждаем правила с людьми, которые знают работу. Используем одинаковые слова в разговоре и коде. Помещаем правила в модель, чтобы сайт, бот и API применяли их одинаково."},{"q":"DDD — это обязательно микросервисы?","a":"Нет. Модель и отдельные области можно организовать внутри одного приложения."}],"extra":"Для простого справочника DDD может быть избыточным. Подход полезен, когда правил много, они меняются и ошибки в них дорого обходятся.","sources":[["Эрик Эванс: DDD Reference","https://www.domainlanguage.com/ddd/reference/"]],"explain":["DDD — предметно-ориентированное проектирование. Разработчик сначала разбирается, как люди работают и какие правила должны соблюдаться, затем отражает это в названиях и поведении программы.","Для переговорок это просто: «бронь», «организатор», «перенос» в разговоре означают то же, что Booking, OrganizerId и Reschedule в коде. Модель — выбранные объекты и их действия, с помощью которых решаем задачу бронирования.","Подход полезен, когда правила меняются и разные люди понимают их по-разному. Для справочника из пары полей можно обойтись обычным CRUD. На этой паре коротко напомним идею, затем будем выбирать правила и проверять свой проект на примерах."],"lecture":"Лекция «Что такое DDD»: понимание предметной области разработчиком. Напоминание занимает 2 минуты."}];
